.css-1op36ck {स्थिति: सापेक्ष; z-सूचकांक: 1;} @ मीडिया (अधिकतम-चौड़ाई: 1069.95px) {@ मीडिया (मिनट-चौड़ाई: 0px) और (अधिकतम-चौड़ाई: 767.95px) {.css-1op36ck:has ([डेटा-स्लॉट-तैयार = "सत्य"]) {मार्जिन-ब्लॉक-अंत: var (--मोबाइल-विजेट-अंतराल, 16px);पैडिंग-ब्लॉक: var (--विजेट-एक्स्ट्रा-पैडिंग, 12px);}} @ मीडिया (मिनट-चौड़ाई: 768px) और (अधिकतम-चौड़ाई: 1069.95px) {.css-1op36ck:has ([डेटा-स्लॉट-तैयार = "सत्य"]) {मार्जिन-ब्लॉक-अंत: var (--मोबाइल-विजेट-अंतराल, 16px);पैडिंग-ब्लॉक: var (--विजेट-अतिरिक्त-पैडिंग, 12px);}} @ मीडिया (मिनट-चौड़ाई: 1070px) {.css-1op36ck:has ([डेटा-स्लॉट-तैयार = "सत्य"]) {मार्जिन-ब्लॉक-अंत: var (--डेस्कटॉप-विजेट-अंतराल, 18px);}}} @ मीडिया (अधिकतम-चौड़ाई: 1069.95px) {.css-1op36ck:has ([डेटा-स्लॉट-संकुचन = "सत्य"]) {इनलाइन-आकार: 1px;ब्लॉक-आकार: 1px;मिनट-इनलाइन-आकार: 1px; अधिकतम-इनलाइन-आकार:1px;मिनट-ब्लॉक-आकार:1px;अधिकतम-ब्लॉक-आकार:1px;मार्जिन:0;पैडिंग:0;सीमा:कोई भी;पृष्ठभूमि-रंग:पारदर्शी;}}

नेपाल तखन व्यवस्था जे किछु कहैत अछि से केलक। ई उचित चैनल, यूएन फंड फॉर रिस्पांडिंग टू लॉस एंड डेमेज के माध्यम स॑ गेलै आरू अपनऽ आग्रह क॑ चैरिटी के बजाय दायित्व के मामला के रूप म॑ फ्रेमिंग करलकै – जे देश लेली सही फ्रेमिंग छै जे वैश्विक ग्रीनहाउस गैस के 0.1 प्रतिशत स॑ भी कम उत्सर्जन करै छै । जवाब प्रक्रियागत रहल अछि। फंड केरऽ निर्माण के बाद स॑ एको डॉलर जारी नै करलऽ गेलऽ छै आरू एकरऽ पहलऽ फैसला दिसंबर म॑ ही होय वाला छै । एतेक धरि जे अपन बोर्ड सेहो आपात बैसार लेल कहलक अछि।

से सेट करू जे बाकी सब किछु कतेक जल्दी चलैत अछि। ओही किछु सप्ताह में कैलेंडर सभा सं भरल छल : इस्तांबुल में जलवायु वित्त सप्ताह, अजरबैजान के बाकू में एक सप्ताह मुख्य कार्यकारी बैसार आ पलाऊ में प्रशांत नेता लोकनिक शिखर सम्मेलन. मोबिलाइजेशन के कोनो कमी नै छै, खाली वू तरह के नै छै जे एक खाता स दोसर खाता में पैसा पहुंचाबै छै।

जे कोष तीन उच्च स्तरीय बैठक करय मे जे समय लगैत अछि ओहि मे कोनो शोक संतप्त देश के दू करोड़ अमेरिकी डॉलर नहि भेज सकैत अछि ओ एखन धरि कोष नहि अछि. ई एकटा लेटरहेड वाला वादा अछि।

